def transform(grid):
    # Recolor the incomplete border endpoint marker using the distinct color from the frame.
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for c in row:
            counts[c] = counts.get(c, 0) + 1
    bg = max(counts, key=counts.get)
    nonbg = [c for c in counts if c != bg]
    if not nonbg:
        return out
    frame = max(nonbg, key=lambda c: counts[c])
    # Find the open rectangular outline and close its missing corners/segments by coloring
    # all positions along its bounding rectangle where outline continuity is intended.
    pts = [(r, col) for r,row in enumerate(grid) for col,v in enumerate(row) if v == frame]
    r0,r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0,c1 = min(c for r,c in pts), max(c for r,c in pts)
    # Only recolor any isolated alternate-color pixel embedded in the frame outline to its frame color.
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if out[r][c] != bg and out[r][c] != frame:
                out[r][c] = frame
    return out
